import{_ as t,o,c as a,ah as i}from"./chunks/framework.DDXs_i7t.js";const d=JSON.parse('{"title":"Social Media Cheat-Sheet – Challenging the System","description":"The art of intervention – and how we respond. A collection of pointed, satirical, and fact-based responses to the defense lines of the current political actors.","frontmatter":{"title":"Social Media Cheat-Sheet – Challenging the System","description":"The art of intervention – and how we respond. A collection of pointed, satirical, and fact-based responses to the defense lines of the current political actors."},"headers":[],"relativePath":"en/recherche/social-media-cheat-sheet.md","filePath":"en/recherche/social-media-cheat-sheet.md"}'),s={name:"en/recherche/social-media-cheat-sheet.md"};function n(r,e,l,h,c,p){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="social-media-cheat-sheet-challenging-the-system" tabindex="-1">Social Media Cheat-Sheet: Challenging the System <a class="header-anchor" href="#social-media-cheat-sheet-challenging-the-system" aria-label="Permalink to &quot;Social Media Cheat-Sheet: Challenging the System&quot;">​</a></h1><p><strong>The art of intervention – and how we respond.</strong></p><p>As part of our mockumentary project <em>“The Horten Mystery,”</em> we not only document the power structures but also enter into a dialogue with the actors of current politics. Here you will find a collection of pointed, satirical, and fact-based responses specifically tailored to the defense lines of the ÖVP and FPÖ.</p><hr><h2 id="🏛️-focus-ovp-topic-political-patronage-citizen-s-request" tabindex="-1">🏛️ Focus: ÖVP (Topic: Political Patronage / &quot;Citizen&#39;s Request&quot;) <a class="header-anchor" href="#🏛️-focus-ovp-topic-political-patronage-citizen-s-request" aria-label="Permalink to &quot;🏛️ Focus: ÖVP (Topic: Political Patronage / &quot;Citizen&#39;s Request&quot;)&quot;">​</a></h2><p><strong>When they say:</strong> <em>“I&#39;m just committed to the region / That was a normal citizen&#39;s request.”</em></p><ul><li><strong>Response 1:</strong> “Interesting. Since when is a 98-point qualification a &#39;citizen&#39;s request&#39; that needs to be &#39;optimized&#39; with 62 points? Asking for a friend named Christa Scharf. #Patronage”</li><li><strong>Response 2:</strong> “Every SMS is a point in the mosaic. We call it the <strong>Pointillism of Power</strong>. From a distance, you see the whole picture of corruption; up close, they are &#39;just favors.&#39; #HortenMystery”</li></ul><p><strong>When they say:</strong> <em>“The justice system is politicized / We are victims of a hunting party.”</em></p><ul><li><strong>Response 3:</strong> “Anyone who declares the rule of law a &#39;hunting party&#39; is usually afraid of the facts. A 98-point hearing doesn&#39;t lie, nor do SMS messages. #WKStA”</li></ul><hr><h2 id="🦅-focus-fpo-topic-rosenkranz-inquiry-committee" tabindex="-1">🦅 Focus: FPÖ (Topic: Rosenkranz / Inquiry Committee) <a class="header-anchor" href="#🦅-focus-fpo-topic-rosenkranz-inquiry-committee" aria-label="Permalink to &quot;🦅 Focus: FPÖ (Topic: Rosenkranz / Inquiry Committee)&quot;">​</a></h2><p><strong>When they say:</strong> <em>“We protect democracy / Fighting the system.”</em></p><ul><li><strong>Response 4:</strong> “Protecting democracy by leading inquiry committees with party loyalty instead of objectivity? That&#39;s not protection; that&#39;s walling in the truth. #Rosenkranz”</li></ul><p><strong>When they say:</strong> <em>“All lies of the system media.”</em></p><ul><li><strong>Response 5:</strong> “When facts (like bank statements and chats) become &#39;lies,&#39; the script of post-truth is complete. We are currently filming it as a mockumentary. #HortenMystery”</li></ul><hr><h2 id="🎭-universal-mockumentary-promos" tabindex="-1">🎭 Universal Mockumentary Promos <a class="header-anchor" href="#🎭-universal-mockumentary-promos" aria-label="Permalink to &quot;🎭 Universal Mockumentary Promos&quot;">​</a></h2><p>Use these responses to draw attention to our project:</p><ul><li>“Thanks for this live content! This fits perfectly in Scene 42 (&#39;The Aesthetic of Small Things&#39;). We are currently re-enacting this. #HortenMystery”</li><li>“Is this already the official defense or just a teaser for our film? The similarities to fiction are purely systemic. #PointillismOfMoney”</li></ul><hr><p><strong>Help cast a light on the dark side of power.</strong> Share these responses and link to:</p><ul><li><a href="https://dokfilm.pages.dev/" target="_blank" rel="noreferrer">https://dokfilm.pages.dev/</a> (Cloudflare)</li><li><a href="https://hadawig.github.io/dokfilm" target="_blank" rel="noreferrer">https://hadawig.github.io/dokfilm</a> (GitHub)</li><li><a href="https://www.youtube.com/@VoltiSodala-p6p" target="_blank" rel="noreferrer">YouTube Channel</a></li></ul>',22)])])}const m=t(s,[["render",n]]);export{d as __pageData,m as default};
